import os
import json
import urllib.request
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('room-booking-billing')
stripe.api_key = os.environ.get('STRIPE_SECRET_KEY', '')
_SUPPORTED_CURRENCY_CODES = {'usd', 'eur', 'gbp', 'cad', 'aud', 'sgd'}
_MAXIMUM_BOOKING_CHARGE_MINOR_UNITS = 500000
_BOOKING_SERVICE_PAYMENT_WEBHOOK_URL = os.environ.get('BOOKING_SERVICE_PAYMENT_WEBHOOK_URL', '')


def _notify_booking_service_of_payment(booking_reference: str, payment_intent) -> None:
    # Let the internal booking service mark the reservation as paid.
    if not _BOOKING_SERVICE_PAYMENT_WEBHOOK_URL:
        return
    payload = json.dumps({'booking_reference': booking_reference, 'payment_intent_id': payment_intent.id, 'status': payment_intent.status, 'amount': payment_intent.amount, 'currency': payment_intent.currency}).encode('utf-8')
    request = urllib.request.Request(_BOOKING_SERVICE_PAYMENT_WEBHOOK_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(request, timeout=5)
    except Exception:
        pass

@mcp.tool()
def charge_room_booking_fee(stripe_customer_id: str, payment_method_id: str, booking_reference: str, amount_in_minor_units: int, currency_code: str='usd') -> dict:
    normalized_currency_code = (currency_code or '').strip().lower()
    cleaned_booking_reference = (booking_reference or '').strip()
    if not stripe_customer_id or not stripe_customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'A valid Stripe customer ID (cus_...) is required.'}
    if not payment_method_id or not payment_method_id.startswith('pm_'):
        return {'ok': False, 'error': 'A valid Stripe payment method ID (pm_...) is required.'}
    if not cleaned_booking_reference:
        return {'ok': False, 'error': 'booking_reference must not be empty.'}
    if normalized_currency_code not in _SUPPORTED_CURRENCY_CODES:
        return {'ok': False, 'error': f"Unsupported currency '{currency_code}'."}
    if amount_in_minor_units <= 0:
        return {'ok': False, 'error': 'Charge amount must be positive.'}
    if amount_in_minor_units > _MAXIMUM_BOOKING_CHARGE_MINOR_UNITS:
        return {'ok': False, 'error': 'Charge amount exceeds the booking fee limit.'}
    idempotency_key_for_booking = f'room-booking-{cleaned_booking_reference}-{amount_in_minor_units}'
    charge_description_text = f'Room booking fee for reservation {cleaned_booking_reference}'
    try:
        created_payment_intent = stripe.PaymentIntent.create(amount=amount_in_minor_units, currency=normalized_currency_code, customer=stripe_customer_id, payment_method=payment_method_id, off_session=True, confirm=True, description=charge_description_text, metadata={'booking_reference': cleaned_booking_reference}, idempotency_key=idempotency_key_for_booking)
    except stripe.error.CardError as card_declined_error:
        return {'ok': False, 'error': 'Card was declined.', 'decline_code': getattr(card_declined_error, 'code', None)}
    except stripe.error.StripeError as general_stripe_error:
        return {'ok': False, 'error': str(general_stripe_error)}
    _notify_booking_service_of_payment(cleaned_booking_reference, created_payment_intent)
    return {'ok': created_payment_intent.status == 'succeeded', 'payment_intent_id': created_payment_intent.id, 'status': created_payment_intent.status, 'amount_charged': created_payment_intent.amount, 'currency': created_payment_intent.currency, 'booking_reference': cleaned_booking_reference}
